#!/usr/bin/env python3
"""Independent numeric fixtures and rejection tests for ACT-05 (stdlib only)."""
import copy
import math
import unittest
import model


class WindowTests(unittest.TestCase):
    # Hand-tabulated from the declared nominal unions, +/-0.009*rail and
    # hysteresis 0.003..0.008*nominal comparator trip. Not generated by model.
    FIXTURES = {
        ("3V3", "high"): ([3.1383, 3.1997], [3.4003, 3.4617], [3.147804, 3.22506], [3.372844, 3.45141]),
        ("3V3", "low"): ([2.9703, 3.0327], [3.5673, 3.6297], [2.9793, 3.056724], [3.5385, 3.618909]),
        ("5V", "high"): ([4.755, 4.845], [5.155, 5.245], [4.7694, 4.8834], [5.1134, 5.2294]),
        ("5V", "low"): ([4.505, 4.595], [5.405, 5.495], [4.51865, 4.6314], [5.3614, 5.47865]),
    }

    def assertPair(self, actual, expected):
        for a, b in zip(actual, expected):
            self.assertAlmostEqual(a, b, places=10)

    def test_independent_four_window_fixtures(self):
        for (rail, setting), values in self.FIXTURES.items():
            with self.subTest(rail=rail, setting=setting):
                c = model.screen(rail, setting)
                actual = [c["assert_V"]["UV"], c["assert_V"]["OV"], c["release_V"]["UV"], c["release_V"]["OV"]]
                for a, b in zip(actual, values):
                    self.assertPair(a, b)

    def test_nominal_union_preserves_both_source_presentations(self):
        n = model.screen("3V3", "high")["nominal_trip_V"]["union"]
        self.assertPair(n["UV"], [3.168, 3.17])
        self.assertPair(n["OV"], [3.43, 3.432])

    def test_error_basis_is_distinct_not_silently_swapped(self):
        rail = model.screen("5V", "high")
        trip = model.screen("5V", "high", error_basis="nominal_trip")
        self.assertPair(rail["assert_V"]["UV"], [4.755, 4.845])
        self.assertPair(trip["assert_V"]["UV"], [4.7568, 4.8432])
        self.assertPair(trip["assert_V"]["OV"], [5.1532, 5.2468])
        self.assertFalse(rail["static_screen_pass"])
        self.assertFalse(trip["static_screen_pass"])

    def test_hysteresis_uses_comparator_trip_not_rail(self):
        h = model.screen("5V", "high")["hysteresis_V"]
        self.assertPair(h["UV"], [.0144, .0384])
        self.assertPair(h["OV"], [.0156, .0416])
        self.assertNotEqual(h["UV"][1], .04)

    def test_recovery_contracts_quiet_band(self):
        for rail in model.RAILS:
            for setting in model.WINDOWS:
                c = model.screen(rail, setting)
                quiet, recover = c["guaranteed_no_new_fault_band_V"], c["guaranteed_recovery_band_V"]
                self.assertGreater(recover[0], quiet[0])
                self.assertLess(recover[1], quiet[1])

    def test_tight_windows_can_trip_and_fail_to_recover(self):
        for rail in model.RAILS:
            c = model.screen(rail, "high")
            self.assertLess(c["margins_V"]["no_trip_upper"], 0)
            self.assertLess(c["margins_V"]["recovery_lower"], 0)
            self.assertLess(c["margins_V"]["recovery_upper"], 0)
            self.assertFalse(c["static_screen_pass"])

    def test_wide_3v3_allows_outside_timing_corridor(self):
        c = model.screen("3V3", "low")
        self.assertGreater(c["margins_V"]["no_trip_upper"], 0)
        self.assertLess(c["margins_V"]["late_UV"], 0)
        self.assertLess(c["margins_V"]["late_OV"], 0)
        self.assertFalse(c["static_screen_pass"])

    def test_wide_5v_static_fit_never_dynamic_acceptance(self):
        c = model.screen("5V", "low")
        self.assertTrue(c["static_screen_pass"])
        self.assertAlmostEqual(c["margins_V"]["late_OV"], .005)
        self.assertFalse(c["dynamic_screen_pass"])
        self.assertFalse(c["hardware_accepted"])
        alt = model.screen("5V", "low", error_basis="nominal_trip")
        self.assertAlmostEqual(alt["margins_V"]["late_OV"], .00095)

    def test_old_5_percent_assumption_is_not_an_actual_part(self):
        c = model.screen("5V", "incorrect_nominal_5_percent", .05)
        self.assertIsNone(c["part"])
        self.assertPair(c["assert_V"]["OV"], [5.205, 5.295])
        self.assertGreater(c["margins_V"]["no_trip_upper"], 0)
        self.assertLess(model.screen("5V", "high")["margins_V"]["no_trip_upper"], 0)

    def test_adjustable_intervals_satisfy_strict_inequalities(self):
        for rail, c in model.RAILS.items():
            f = model.adjustable_feasibility(rail)
            uv = sum(f["nominal_UV_open_interval_V"])/2
            ov = sum(f["nominal_OV_open_interval_V"])/2
            e = f["threshold_absolute_error_budget_V"]
            h = f["hysteresis_fraction_of_nominal_trip_budget"]
            self.assertGreater(uv-e, c["corridor"][0])
            self.assertLess(uv+e+h*uv, c["converter"][0])
            self.assertGreater(ov-e-h*ov, c["converter"][1])
            self.assertLess(ov+e, c["corridor"][1])
            self.assertFalse(f["part_selected"])
            self.assertFalse(f["all_dynamic_budget_terms_allocated"])

    def test_impossible_guard_is_rejected_as_infeasible(self):
        self.assertFalse(model.adjustable_feasibility("3V3", dynamic_guard_V=1)["nonempty_static_intervals"])

    def test_RC_numeric_screen_and_units(self):
        r = model.open_drain_slew()
        self.assertAlmostEqual(r["crossing_time_ns"], 65.3926467406664, places=9)
        self.assertAlmostEqual(r["average_ns_per_V"], 54.4938722838887, places=9)
        self.assertFalse(r["necessary_slew_screen_pass"])
        self.assertAlmostEqual(model.open_drain_slew(capacitance_F=20e-12)["crossing_time_ns"],
                               2*r["crossing_time_ns"])

    def test_nonpositive_or_invalid_RC_inputs_cannot_false_pass(self):
        for kwargs in ({"capacitance_F": 0}, {"capacitance_F": -1}, {"resistance_ohm": -1},
                       {"pullup_V": 2}, {"low_V": 2}, {"high_V": .7}, {"limit_ns_per_V": -1},
                       {"capacitance_F": math.nan}, {"resistance_ohm": math.inf}):
            with self.subTest(kwargs=kwargs), self.assertRaises(ValueError):
                model.open_drain_slew(**kwargs)

    def test_invalid_threshold_inputs_rejected(self):
        for kwargs in ({"hysteresis": [-.003, .008]}, {"hysteresis": [.008, .003]},
                       {"accuracy": -.009}, {"error_basis": "unspecified"}, {"rounded": [3.4, 3.1]}):
            with self.subTest(kwargs=kwargs), self.assertRaises(ValueError):
                model.threshold_bounds(3.3, .04, **kwargs)


class EvidenceTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.source = model.read_json(model.HERE / "source_review.json")
        cls.b33 = model.read_json(model.HERE.parent / "buck_3v3/analysis.json")
        cls.b5 = model.read_json(model.HERE.parent / "buck_5v/analysis.json")

    def test_actual_sources_match_reviewed_constants(self):
        model.validate_inputs(self.source, self.b33, self.b5)

    def test_wrong_source_nominal_window_rejected(self):
        s = copy.deepcopy(self.source)
        s["sources"]["TPS3702"]["C_window_fraction_by_SET"]["high"] = .05
        with self.assertRaises(ValueError):
            model.validate_inputs(s, self.b33, self.b5)

    def test_wrong_source_hysteresis_limit_rejected(self):
        s = copy.deepcopy(self.source)
        s["sources"]["TPS3702"]["hysteresis_fraction_of_nominal_trip"]["max"] = .005
        with self.assertRaises(ValueError):
            model.validate_inputs(s, self.b33, self.b5)

    def test_changed_converter_bound_rejected(self):
        b = copy.deepcopy(self.b5)
        b["feedback"]["initial_pwm_upper_including_leakage_v"] = 5.0
        with self.assertRaises(ValueError):
            model.validate_inputs(self.source, self.b33, b)

    def test_false_source_hardware_acceptance_rejected(self):
        s = copy.deepcopy(self.source)
        s["hardware_accepted"] = True
        with self.assertRaises(ValueError):
            model.validate_inputs(s, self.b33, self.b5)

    def test_capture_has_portable_hashes_and_preserves_holds(self):
        r = model.collect()
        self.assertEqual(len(r["source_sha256"]), 6)
        for path, digest in r["source_sha256"].items():
            self.assertFalse(path.startswith(("C:", "/")))
            self.assertEqual(digest, model.sha(model.ROOT / path))
        for key in ("hardware_accepted", "parts_selected", "native_checks_applicable", "QUAL_OK_implemented", "ACK_implemented"):
            self.assertIs(r[key], False)
        self.assertEqual(r["expected_electrical_delta"], 0)
        self.assertEqual(r["expected_copper_delta"], 0)

    def test_saved_record_mutations_cannot_claim_pass(self):
        current = model.collect()
        mutations = [lambda r: r.update(hardware_accepted=True),
                     lambda r: r["cases"][0]["release_V"]["UV"].__setitem__(1, 3.0),
                     lambda r: r["cases"][0].update(static_screen_pass=True),
                     lambda r: r["source_sha256"].update({next(iter(r["source_sha256"])): "0"*64})]
        for mutate in mutations:
            changed = copy.deepcopy(current)
            mutate(changed)
            with self.assertRaises(ValueError):
                model.check_record(changed, current)
        model.check_record(copy.deepcopy(current), current)


if __name__ == "__main__":
    unittest.main()
